/**
 * @module format
 * @description 文件格式相关工具函数与常量定义。
 * 包括支持的输入/输出格式列表、文件名解析、字节格式化、MIME 类型推断等。
 */

/** 支持的输入文件扩展名 */
export const supportedInputExts = ['ply', 'compressed.ply', 'sog', 'meta.json', 'spz', 'splat', 'ksplat', 'lcc'];

/** 格式转换支持的输出扩展名 */
export const transformOutputExts = ['ply', 'compressed.ply', 'sog', 'meta.json', 'spz', 'glb', 'csv', 'html'];

/** LOD 构建支持的输入扩展名 */
export const lodInputExts = ['ply', 'spz'];

/** LOD 输出格式 */
export const lodOutputFormats = ['rad', 'rad-chunked', 'spz', 'spz-chunked'] as const;

/**
 * 将字节数格式化为人类可读的字符串。
 * @example formatBytes(1536) // '1.5 KB'
 */
export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes)) return '-';
  const units = ['B', 'KB', 'MB', 'GB'];
  let value = bytes;
  let index = 0;
  while (value >= 1024 && index < units.length - 1) {
    value /= 1024;
    index += 1;
  }
  return `${value.toFixed(value >= 10 || index === 0 ? 0 : 1)} ${units[index]}`;
}

/**
 * 从文件路径中提取不含扩展名的基础名称。
 * 特殊处理 `.compressed.ply` 和 `meta.json`。
 * @example basename('path/to/model.spz') // 'model'
 */
export function basename(name: string): string {
  const leaf = name.split(/[\\/]/).pop() || name;
  if (leaf.endsWith('.compressed.ply')) return leaf.slice(0, -'.compressed.ply'.length);
  if (leaf.endsWith('meta.json')) return leaf.slice(0, -'meta.json'.length).replace(/[\\/]$/, '') || 'scene';
  const dot = leaf.lastIndexOf('.');
  return dot > 0 ? leaf.slice(0, dot) : leaf;
}

/**
 * 从文件名中提取扩展名（小写，不含 `.`）。
 * 会去除 URL query/hash 部分，特殊处理复合扩展名。
 * @example extensionOf('model.compressed.ply') // 'compressed.ply'
 */
export function extensionOf(name: string): string {
  const clean = name.split(/[?#]/)[0].toLowerCase();
  if (clean.endsWith('.compressed.ply')) return 'compressed.ply';
  if (clean.endsWith('meta.json')) return 'meta.json';
  const dot = clean.lastIndexOf('.');
  return dot >= 0 ? clean.slice(dot + 1) : '';
}

/**
 * 根据输入文件名和目标扩展名生成输出文件名。
 * @example outputFilename('model.ply', 'spz') // 'model.spz'
 * @example outputFilename('scene.ply', 'meta.json') // 'scene/meta.json'
 */
export function outputFilename(inputName: string, outputExt: string): string {
  const base = basename(inputName) || 'output';
  return outputExt === 'meta.json' ? `${base}/meta.json` : `${base}.${outputExt}`;
}

/**
 * 根据文件名推断 MIME 类型。
 * @example mimeForName('viewer.html') // 'text/html;charset=utf-8'
 */
export function mimeForName(name: string): string {
  const ext = extensionOf(name);
  if (ext === 'html') return 'text/html;charset=utf-8';
  if (ext === 'csv') return 'text/csv;charset=utf-8';
  if (ext === 'json' || ext === 'meta.json') return 'application/json';
  if (ext === 'zip') return 'application/zip';
  return 'application/octet-stream';
}
