import type { OutputFile } from '../core/types';
import { downloadOutput } from '../core/download';
import { formatBytes } from '../core/format';

export class ResultCard {
  readonly element = document.createElement('section');
  private files: OutputFile[] = [];

  constructor() {
    this.element.className = 'result-card hidden';
    this.element.innerHTML = `
      <div class="result-head">
        <div><span class="success-dot"></span><strong>转换完成</strong><p>结果文件已在浏览器内生成</p></div>
        <button class="primary-btn" data-action="download">下载结果</button>
      </div>
      <div class="result-files"></div>
    `;
    this.element.querySelector('[data-action="download"]')?.addEventListener('click', () => {
      downloadOutput(this.files, this.files.length === 1 ? this.files[0].name : 'splat-output');
    });
  }

  setFiles(files: OutputFile[]): void {
    this.files = files;
    this.element.classList.toggle('hidden', files.length === 0);
    const list = this.element.querySelector('.result-files') as HTMLElement;
    list.innerHTML = files.map((file) => `
      <div class="result-file">
        <span>${file.name}</span>
        <em>${formatBytes(file.data.byteLength)}</em>
      </div>
    `).join('');
  }

  clear(): void {
    this.setFiles([]);
  }
}
