import { FileInput } from '../components/FileInput';
import { ParamPanel } from '../components/ParamPanel';
import { algorithmOptions, defaultLodParams } from '../core/lodSchema';
import type { InputFile, LodParams } from '../core/types';

export class LodView {
  readonly element = document.createElement('div');
  private files: InputFile[] = [];
  private params: LodParams = structuredClone(defaultLodParams);

  constructor(private readonly onRun: (files: InputFile[], params: LodParams) => void, onNotice: (text: string, level?: 'info' | 'warn' | 'error') => void) {
    this.element.className = 'workspace';
    const input = new FileInput((files) => { this.files = files; }, onNotice);
    const panel = new ParamPanel<LodParams>('Spark LOD 构建参数', [
      { key: 'algorithm', label: 'LOD 算法', type: 'select', options: algorithmOptions.map((option) => ({ value: option.value, label: option.label })), help: 'quality 最稳，bhatt/tiny 可自定义 base' },
      { key: 'base', label: 'LOD Base', type: 'number', min: 1.1, max: 16, step: 0.05, help: '越大层级越少、文件越小、渐进跳跃越明显' },
      { key: 'outputFormat', label: '输出格式', type: 'select', options: ['rad', 'rad-chunked', 'spz', 'spz-chunked'].map((value) => ({ value, label: value })), help: 'chunked 会输出多文件并自动 ZIP' },
      { key: 'maxSh', label: 'Max SH', type: 'number', min: 0, max: 3, step: 1, help: '限制最大球谐阶数' },
      { key: 'skipValidate', label: '跳过 finite 校验', type: 'checkbox', help: '仅在输入存在已知异常时使用' },
      { key: 'inflate', label: 'Inflate Scale', type: 'checkbox', help: '将 LOD opacity 膨胀回普通 splat 透明度' }
    ], this.params, (values) => {
      this.params = {
        ...this.params,
        ...values,
        base: Number(values.base),
        maxSh: Number(values.maxSh)
      };
    });

    const run = document.createElement('section');
    run.className = 'param-panel glass-card';
    run.innerHTML = `
      <div class="section-title"><span>03</span><div><h2>执行</h2><p>首次运行会异步加载 build-lod WASM</p></div></div>
      <p class="hint">LOD 构建完全在浏览器内进行，不会上传文件。若 WASM 产物尚未生成，会显示明确的初始化失败提示。</p>
      <button class="primary-btn" data-run="lod" style="margin-top:18px">开始构建 LOD</button>
    `;
    run.querySelector('[data-run="lod"]')?.addEventListener('click', () => this.onRun(this.files, this.params));

    const right = document.createElement('div');
    right.className = 'right-stack';
    right.append(panel.element, run);
    this.element.append(input.element, right);
  }
}
