/**
 * @module download
 * @description 浏览器端文件下载与打包逻辑。
 * 单文件直接触发下载，多文件使用 fflate 打成 ZIP 后下载。
 */

import { zipSync } from 'fflate';
import type { OutputFile } from './types';
import { basename, mimeForName } from './format';

/**
 * 创建临时 `<a>` 标签触发浏览器下载。
 * 下载后 1 秒自动释放 Object URL。
 */
function triggerDownload(name: string, data: Uint8Array | Blob, mimeType = 'application/octet-stream'): void {
  const blob = data instanceof Blob ? data : new Blob([data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength) as ArrayBuffer], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = name;
  anchor.rel = 'noopener';
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * 下载输出文件。
 * - 单文件：直接触发浏览器下载
 * - 多文件：打成 ZIP 后下载（文件名中的 `/` 会保留为 ZIP 内目录结构）
 * @param files - 要下载的输出文件列表
 * @param suggestedBase - ZIP 文件名建议基础名
 */
export function downloadOutput(files: OutputFile[], suggestedBase = 'splat-output'): void {
  if (files.length === 0) return;
  if (files.length === 1) {
    const file = files[0];
    triggerDownload(file.name, file.data, file.mimeType || mimeForName(file.name));
    return;
  }

  const entries: Record<string, Uint8Array> = {};
  for (const file of files) {
    entries[file.name] = file.data;
  }
  const zipped = zipSync(entries, { level: 6 });
  triggerDownload(`${basename(suggestedBase)}.zip`, zipped, 'application/zip');
}

/**
 * 确保所有输出文件的 data 字段为 Uint8Array。
 * Worker postMessage 后类型可能丢失，此函数做兼容转换。
 */
export function normalizeOutputFiles(files: OutputFile[]): OutputFile[] {
  return files.map((file) => ({
    ...file,
    data: file.data instanceof Uint8Array ? file.data : new Uint8Array(file.data)
  }));
}
