import type { ProgressState } from '../core/types';

export class ProgressBar {
  readonly element = document.createElement('div');
  private fill: HTMLElement;
  private label: HTMLElement;

  constructor() {
    this.element.className = 'progress-card';
    this.element.innerHTML = `
      <div class="progress-meta"><span>任务进度</span><strong>0%</strong></div>
      <div class="progress-track"><div class="progress-fill"></div></div>
      <p class="progress-label">等待开始</p>
    `;
    this.fill = this.element.querySelector('.progress-fill') as HTMLElement;
    this.label = this.element.querySelector('.progress-label') as HTMLElement;
  }

  set(progress: ProgressState): void {
    const value = Math.max(0, Math.min(100, progress.value));
    this.fill.style.width = `${value}%`;
    const strong = this.element.querySelector('strong');
    if (strong) strong.textContent = `${Math.round(value)}%`;
    this.label.textContent = progress.label;
  }
}
