import { LogPanel } from './components/LogPanel';
import { ProgressBar } from './components/ProgressBar';
import { ResultCard } from './components/ResultCard';
import { TabBar, type TabId } from './components/TabBar';
import { JobManager } from './core/jobManager';
import type { InputFile, LodJobPayload, LodParams, OutputFile, TransformJobPayload, TransformParams } from './core/types';
import { ConvertView } from './views/ConvertView';
import { LodView } from './views/LodView';

export class App {
  private readonly root: HTMLElement;
  private activeTab: TabId = 'convert';
  private readonly content = document.createElement('main');
  private readonly progress = new ProgressBar();
  private readonly result = new ResultCard();
  private readonly logs = new LogPanel();
  private currentJob?: JobManager<TransformJobPayload | LodJobPayload>;
  private runCard!: HTMLElement;
  private tabbar!: TabBar;

  constructor(root: HTMLElement) {
    this.root = root;
  }

  mount(): void {
    const shell = document.createElement('div');
    shell.className = 'app-shell';
    shell.innerHTML = `
      <header class="topbar">
        <div class="logo"><div class="logo-mark">S</div><div><strong>Splat Studio</strong><span>3DGS Converter · Browser only</span></div></div>
        <div data-slot="tabs"></div>
        <div class="top-actions"><button class="ghost-btn" data-action="theme">切换主题</button><a class="ghost-btn" href="../" target="_blank" rel="noopener">Workspace</a></div>
      </header>
      <section class="hero">
        <h1><span class="gradient-text">3D Gaussian Splat</span><br/>在线转换与 LOD 构建</h1>
        <p>本地文件不上传服务器。支持 splat-transform 多格式转换；Spark build-lod 通过 WASM 在浏览器内构建 RAD / SPZ 分块输出。</p>
      </section>
      <div class="notice-stack" data-slot="notices"></div>
    `;
    this.content.className = 'view-root';
    shell.appendChild(this.content);

    this.runCard = document.createElement('section');
    this.runCard.className = 'run-card glass-card';
    this.runCard.innerHTML = `
      <span class="run-label">当前运行任务</span>
      <div data-slot="progress"></div>
      <button class="ghost-btn" data-action="cancel">取消</button>
    `;
    this.runCard.querySelector('[data-slot="progress"]')?.appendChild(this.progress.element);
    this.runCard.querySelector('[data-action="cancel"]')?.addEventListener('click', () => this.currentJob?.cancel());
    shell.append(this.runCard, this.result.element, this.logs.element);

    this.tabbar = new TabBar(this.activeTab, (tab) => {
      this.activeTab = tab;
      this.tabbar.setActive(tab);
      this.renderView();
      window.location.hash = tab;
    });
    shell.querySelector('[data-slot="tabs"]')?.appendChild(this.tabbar.element);
    shell.querySelector('[data-action="theme"]')?.addEventListener('click', () => this.toggleTheme());

    this.root.appendChild(shell);
    const hash = window.location.hash.replace('#', '') as TabId;
    if (hash === 'lod' || hash === 'convert') this.activeTab = hash;
    this.tabbar.setActive(this.activeTab);
    this.renderView();
  }

  private renderView(): void {
    this.content.innerHTML = '';
    const view = this.activeTab === 'convert'
      ? new ConvertView((files, params) => this.runTransform(files, params), (text, level) => this.notice(text, level))
      : new LodView((files, params) => this.runLod(files, params), (text, level) => this.notice(text, level));
    this.content.appendChild(view.element);
  }

  private runTransform(files: InputFile[], params: TransformParams): void {
    if (!this.validateFiles(files)) return;
    this.prepareJob();
    this.currentJob = new JobManager<TransformJobPayload>(() => new Worker(new URL('./workers/transform.worker.ts', import.meta.url), { type: 'module' }), this.callbacks());
    this.currentJob.start({ files, params });
  }

  private runLod(files: InputFile[], params: LodParams): void {
    if (!this.validateFiles(files)) return;
    this.prepareJob();
    this.currentJob = new JobManager<LodJobPayload>(() => new Worker(new URL('./workers/buildLod.worker.ts', import.meta.url), { type: 'module' }), this.callbacks());
    this.currentJob.start({ files, params });
  }

  private callbacks() {
    return {
      onStatus: (status: string) => this.notice(`状态：${status}`, status === 'error' ? 'error' : status === 'cancelled' ? 'warn' : 'info'),
      onProgress: (progress: { value: number; label: string }) => this.progress.set(progress),
      onLog: (entry: any) => this.logs.add(entry),
      onDone: (files: OutputFile[]) => this.result.setFiles(files),
      onError: (error: Error) => this.showError(error)
    };
  }

  private prepareJob(): void {
    this.logs.clear();
    this.result.clear();
    this.progress.set({ value: 0, label: '准备启动' });
  }

  private validateFiles(files: InputFile[]): boolean {
    if (files.length > 0) return true;
    this.notice('请先选择本地文件或添加网络 URL。', 'warn');
    return false;
  }

  private notice(text: string, level: 'info' | 'warn' | 'error' = 'info'): void {
    const stack = document.querySelector('[data-slot="notices"]') as HTMLElement | null;
    if (!stack) return;
    const item = document.createElement('div');
    item.className = `notice ${level}`;
    item.textContent = text;
    stack.appendChild(item);
    window.setTimeout(() => item.remove(), level === 'error' ? 7000 : 3600);
  }

  private showError(error: Error): void {
    this.notice(error.message, 'error');
    this.logs.add({ id: crypto.randomUUID(), level: 'error', time: new Date().toLocaleTimeString(), text: error.stack || error.message });
  }

  private toggleTheme(): void {
    const current = document.documentElement.dataset.theme === 'light' ? 'dark' : 'light';
    document.documentElement.dataset.theme = current;
    localStorage.setItem('splat-studio-theme', current);
  }
}
