/**
 * @module inputResolver
 * @description 输入文件解析器，处理本地文件选择和远程 URL 下载。
 */

import type { InputFile } from './types';

/** 大文件警告阈值（500 MB） */
const LARGE_FILE_WARNING_BYTES = 500 * 1024 * 1024;

/**
 * 将浏览器 FileList/File[] 转为统一的 InputFile 数组。
 * 会读取文件的 ArrayBuffer 数据。
 */
export async function resolveLocalFiles(fileList: FileList | File[]): Promise<InputFile[]> {
  const files = Array.from(fileList);
  return Promise.all(files.map(async (file) => ({
    name: file.webkitRelativePath || file.name,
    data: await file.arrayBuffer(),
    source: 'local' as const,
    size: file.size
  })));
}

/**
 * 从远程 URL 下载文件并返回 InputFile。
 * @throws 当 HTTP 响应非 2xx 时抛出错误
 */
export async function resolveUrl(urlText: string): Promise<InputFile> {
  const url = new URL(urlText.trim());
  const response = await fetch(url, { mode: 'cors' });
  if (!response.ok) {
    throw new Error(`URL 下载失败：${response.status} ${response.statusText}`);
  }
  const data = await response.arrayBuffer();
  const name = decodeURIComponent(url.pathname.split('/').pop() || 'remote-file');
  return {
    name,
    data,
    source: 'url',
    sourceUrl: url.toString(),
    size: data.byteLength
  };
}

/**
 * 检查文件列表中是否有超过 500 MB 的大文件，返回警告文本。
 * 用于在 UI 上提示用户可能的 WASM 内存限制风险。
 */
export function getLargeFileWarnings(files: InputFile[]): string[] {
  return files
    .filter((file) => file.size > LARGE_FILE_WARNING_BYTES)
    .map((file) => `${file.name} 大于 500 MB，浏览器内转换可能触达 WASM 内存上限。`);
}
