import type { LogEntry } from '../core/types';

export class LogPanel {
  readonly element = document.createElement('aside');
  private list: HTMLElement;
  private entries: LogEntry[] = [];

  constructor() {
    this.element.className = 'log-panel collapsed';
    this.element.innerHTML = `
      <div class="log-head">
        <div><strong>运行日志</strong><span>Worker / WASM / splat-transform</span></div>
        <div style="display:flex;gap:8px;align-items:center">
          <button class="ghost-btn" data-action="copy">复制</button>
          <span class="log-toggle">▼</span>
        </div>
      </div>
      <div class="log-list"></div>
    `;
    this.list = this.element.querySelector('.log-list') as HTMLElement;
    this.element.querySelector('.log-head')?.addEventListener('click', (e) => {
      if ((e.target as HTMLElement).closest('[data-action="copy"]')) return;
      this.element.classList.toggle('collapsed');
    });
    this.element.querySelector('[data-action="copy"]')?.addEventListener('click', () => {
      void navigator.clipboard.writeText(this.entries.map((item) => `[${item.time}] ${item.level}: ${item.text}`).join('\n'));
    });
  }

  add(entry: LogEntry): void {
    this.entries.push(entry);
    this.element.classList.remove('collapsed');
    const row = document.createElement('div');
    row.className = `log-row ${entry.level}`;
    row.innerHTML = `<span>${entry.time}</span><b>${entry.level}</b><p></p>`;
    row.querySelector('p')!.textContent = entry.text;
    this.list.appendChild(row);
    this.list.scrollTop = this.list.scrollHeight;
  }

  clear(): void {
    this.entries = [];
    this.list.innerHTML = '';
  }
}
