export type FieldSchema =
  | { key: string; label: string; type: 'text' | 'number'; min?: number; max?: number; step?: number; placeholder?: string; help?: string }
  | { key: string; label: string; type: 'checkbox'; help?: string }
  | { key: string; label: string; type: 'select'; options: { value: string; label: string }[]; help?: string };

export class ParamPanel<T extends Record<string, any>> {
  readonly element = document.createElement('section');

  constructor(title: string, fields: FieldSchema[], private values: T, private readonly onChange: (values: T) => void) {
    this.element.className = 'param-panel glass-card';
    this.element.innerHTML = `
      <div class="section-title"><span>02</span><div><h2>${title}</h2><p>按需要调整转换参数</p></div></div>
      <div class="field-grid"></div>
    `;
    const grid = this.element.querySelector('.field-grid') as HTMLElement;
    for (const field of fields) grid.appendChild(this.renderField(field));
  }

  setValues(values: T): void {
    this.values = values;
    this.element.querySelectorAll<HTMLInputElement | HTMLSelectElement>('[data-key]').forEach((input) => {
      const key = input.dataset.key!;
      const value = this.values[key];
      if (input instanceof HTMLInputElement && input.type === 'checkbox') {
        input.checked = Boolean(value);
      } else {
        input.value = value == null ? '' : String(value);
      }
    });
  }

  private renderField(field: FieldSchema): HTMLElement {
    const wrapper = document.createElement('label');
    wrapper.className = 'field';
    const help = field.help ? `<small>${field.help}</small>` : '';
    if (field.type === 'select') {
      wrapper.innerHTML = `<span>${field.label}</span><select name="${field.key}" data-key="${field.key}">${field.options.map((option) => `<option value="${option.value}">${option.label}</option>`).join('')}</select>${help}`;
    } else if (field.type === 'checkbox') {
      wrapper.className = 'field field-check';
      wrapper.innerHTML = `<input name="${field.key}" type="checkbox" data-key="${field.key}" /><span>${field.label}</span>${help}`;
    } else {
      wrapper.innerHTML = `<span>${field.label}</span><input name="${field.key}" data-key="${field.key}" type="${field.type}" ${field.min != null ? `min="${field.min}"` : ''} ${field.max != null ? `max="${field.max}"` : ''} ${field.step != null ? `step="${field.step}"` : ''} placeholder="${field.placeholder || ''}" />${help}`;
    }
    const input = wrapper.querySelector<HTMLInputElement | HTMLSelectElement>('[data-key]')!;
    input.addEventListener('input', () => this.handleInput(input));
    this.setInputValue(input);
    return wrapper;
  }

  private setInputValue(input: HTMLInputElement | HTMLSelectElement): void {
    const key = input.dataset.key!;
    const value = this.values[key];
    if (input instanceof HTMLInputElement && input.type === 'checkbox') input.checked = Boolean(value);
    else input.value = value == null ? '' : String(value);
  }

  private handleInput(input: HTMLInputElement | HTMLSelectElement): void {
    const key = input.dataset.key!;
    let value: any = input.value;
    if (input instanceof HTMLInputElement && input.type === 'checkbox') value = input.checked;
    if (input instanceof HTMLInputElement && input.type === 'number') value = input.value === '' ? undefined : Number(input.value);
    this.values = { ...this.values, [key]: value };
    this.onChange(this.values);
  }
}
