/**
 * @module jobManager
 * @description Worker 任务生命周期管理器。
 * 负责创建 Worker、监听消息、实时转发 WASM 日志（BroadcastChannel）、取消任务。
 */

import type { LogEntry, OutputFile, ProgressState, WorkerToMainMessage } from './types';

/** Worker 任务回调接口 */
export interface JobCallbacks {
  onStatus(status: 'idle' | 'running' | 'done' | 'error' | 'cancelled'): void;
  onProgress(progress: ProgressState): void;
  onLog(entry: LogEntry): void;
  onDone(files: OutputFile[], summary?: string): void;
  onError(error: Error): void;
}

/**
 * 泛型 Worker 任务管理器。
 * @template TPayload - Worker 启动时发送的 payload 类型
 */
export class JobManager<TPayload> {
  private worker?: Worker;
  private wasmLogChannel?: BroadcastChannel;

  constructor(private readonly workerFactory: () => Worker, private readonly callbacks: JobCallbacks) {}

  start(payload: TPayload): void {
    this.cancel(false);
    const worker = this.workerFactory();
    this.worker = worker;
    this.callbacks.onStatus('running');
    this.callbacks.onProgress({ value: 3, label: 'Worker 已启动' });

    // 监听 WASM 内部通过 BroadcastChannel 实时发送的过程日志
    const bc = new BroadcastChannel('wasm-log');
    this.wasmLogChannel = bc;
    bc.onmessage = (event: MessageEvent<string>) => {
      this.callbacks.onLog({
        id: crypto.randomUUID(),
        time: new Date().toLocaleTimeString(),
        level: 'info',
        text: event.data
      });
    };

    worker.onmessage = (event: MessageEvent<WorkerToMainMessage>) => {
      const message = event.data;
      if (message.type === 'progress') {
        this.callbacks.onProgress(message.payload);
      } else if (message.type === 'log') {
        this.callbacks.onLog({
          id: crypto.randomUUID(),
          time: new Date().toLocaleTimeString(),
          level: message.payload.level,
          text: message.payload.text
        });
      } else if (message.type === 'done') {
        this.callbacks.onStatus('done');
        this.callbacks.onProgress({ value: 100, label: '转换完成' });
        this.callbacks.onDone(message.payload.files, message.payload.summary);
        this.dispose();
      } else if (message.type === 'error') {
        const error = new Error(message.payload.message);
        error.stack = message.payload.stack;
        this.callbacks.onStatus('error');
        this.callbacks.onError(error);
        this.dispose();
      }
    };

    worker.onerror = (event) => {
      this.callbacks.onStatus('error');
      this.callbacks.onError(new Error(event.message || 'Worker 运行失败'));
      this.dispose();
    };

    worker.postMessage(payload);
  }

  cancel(report = true): void {
    if (!this.worker) return;
    this.worker.terminate();
    this.dispose();
    if (report) {
      this.callbacks.onStatus('cancelled');
      this.callbacks.onProgress({ value: 0, label: '已取消' });
      this.callbacks.onLog({ id: crypto.randomUUID(), time: new Date().toLocaleTimeString(), level: 'warn', text: '任务已取消，Worker 已终止。' });
    }
  }

  private dispose(): void {
    this.worker = undefined;
    if (this.wasmLogChannel) {
      this.wasmLogChannel.close();
      this.wasmLogChannel = undefined;
    }
  }
}
