import { FileInput } from '../components/FileInput';
import { ParamPanel } from '../components/ParamPanel';
import { transformOutputExts } from '../core/format';
import { defaultTransformParams } from '../core/transformSchema';
import type { InputFile, TransformParams } from '../core/types';

export class ConvertView {
  readonly element = document.createElement('div');
  private files: InputFile[] = [];
  private params: TransformParams = structuredClone(defaultTransformParams);

  constructor(private readonly onRun: (files: InputFile[], params: TransformParams) => void, onNotice: (text: string, level?: 'info' | 'warn' | 'error') => void) {
    this.element.className = 'workspace';
    const input = new FileInput((files) => { this.files = files; }, onNotice);
    const right = document.createElement('div');
    right.className = 'right-stack';

    const basic = new ParamPanel<TransformParams>('格式转换参数', [
      { key: 'outputExt', label: '输出格式', type: 'select', options: transformOutputExts.map((ext) => ({ value: ext, label: ext })), help: 'meta.json / html 可能输出多文件，会自动 ZIP' },
      { key: 'iterations', label: 'SOG Iterations', type: 'number', min: 1, max: 64, step: 1, help: 'SOG 压缩迭代次数，越高越慢' },
      { key: 'spzVersion', label: 'SPZ Version', type: 'select', options: [{ value: '4', label: '4' }, { value: '3', label: '3' }], help: '写出 SPZ 时使用' },
      { key: 'unbundledHtml', label: 'HTML 使用分离资源', type: 'checkbox', help: '开启后 html 输出会包含 css/js/sog 多文件' }
    ], this.params, (values) => {
      this.params = { ...this.params, ...values, spzVersion: Number(values.spzVersion) as 3 | 4 };
    });

    const actions = document.createElement('section');
    actions.className = 'param-panel glass-card actions-card';
    actions.innerHTML = `
      <div class="section-title"><span>03</span><div><h2>Actions</h2><p>可选处理链，留空则只做格式转换</p></div></div>
      <div class="field-grid">
        <label class="field"><span>Translate</span><input name="translate" data-action="translate" placeholder="0,0,0" /><small>x,y,z 平移</small></label>
        <label class="field"><span>Rotate</span><input name="rotate" data-action="rotate" placeholder="0,0,0" /><small>欧拉角，单位度</small></label>
        <label class="field"><span>Scale</span><input name="scale" data-action="scale" type="number" step="0.01" value="1" /><small>统一缩放</small></label>
        <label class="field"><span>Filter Harmonics</span><select name="filterHarmonics" data-action="filterHarmonics"><option value="">不处理</option><option value="0">0</option><option value="1">1</option><option value="2">2</option><option value="3">3</option></select><small>保留球谐阶数</small></label>
        <label class="field"><span>Decimate</span><input name="decimate" data-action="decimate" placeholder="50% 或 50000" /><small>简化数量或百分比</small></label>
        <label class="field field-check"><input name="filterNaN" data-action="filterNaN" type="checkbox" checked /><span>Filter NaN</span><small>移除 NaN / Inf</small></label>
        <label class="field field-check"><input name="mortonOrder" data-action="mortonOrder" type="checkbox" /><span>Morton Order</span><small>空间局部性排序</small></label>
        <label class="field field-check"><input name="summary" data-action="summary" type="checkbox" /><span>Summary</span><small>输出统计日志</small></label>
      </div>
      <button class="primary-btn" data-run="convert" style="margin-top:18px">开始格式转换</button>
    `;
    actions.addEventListener('input', () => this.syncActions(actions));
    actions.querySelector('[data-run="convert"]')?.addEventListener('click', () => {
      this.syncActions(actions);
      this.onRun(this.files, this.params);
    });

    right.append(basic.element, actions);
    this.element.append(input.element, right);
  }

  private syncActions(root: HTMLElement): void {
    const get = (key: string) => root.querySelector<HTMLInputElement | HTMLSelectElement>(`[data-action="${key}"]`)!;
    const scale = Number((get('scale') as HTMLInputElement).value || '1');
    const filterHarmonicsValue = get('filterHarmonics').value;
    this.params = {
      ...this.params,
      actions: {
        translate: get('translate').value.trim() || undefined,
        rotate: get('rotate').value.trim() || undefined,
        scale: Number.isFinite(scale) && scale !== 1 ? scale : undefined,
        filterHarmonics: filterHarmonicsValue === '' ? undefined : Number(filterHarmonicsValue) as 0 | 1 | 2 | 3,
        decimate: get('decimate').value.trim() || undefined,
        filterNaN: (get('filterNaN') as HTMLInputElement).checked,
        mortonOrder: (get('mortonOrder') as HTMLInputElement).checked,
        summary: (get('summary') as HTMLInputElement).checked
      }
    };
  }
}
