export type TabId = 'convert' | 'lod';

export class TabBar {
  readonly element: HTMLElement;
  private active: TabId;

  constructor(active: TabId, onChange: (tab: TabId) => void) {
    this.active = active;
    this.element = document.createElement('nav');
    this.element.className = 'tabbar';
    this.element.innerHTML = `
      <button class="tab-btn" data-tab="convert">格式转换</button>
      <button class="tab-btn" data-tab="lod">LOD 构建</button>
    `;
    this.element.addEventListener('click', (event) => {
      const target = event.target as HTMLElement;
      const button = target.closest<HTMLButtonElement>('[data-tab]');
      if (!button) return;
      onChange(button.dataset.tab as TabId);
    });
    this.setActive(active);
  }

  setActive(tab: TabId): void {
    this.active = tab;
    this.element.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach((button) => {
      button.classList.toggle('active', button.dataset.tab === this.active);
    });
  }
}
