import { extensionOf, formatBytes } from '../core/format';
import { getLargeFileWarnings, resolveLocalFiles, resolveUrl } from '../core/inputResolver';
import type { InputFile } from '../core/types';

export class FileInput {
  readonly element = document.createElement('section');
  private files: InputFile[] = [];

  constructor(private readonly onChange: (files: InputFile[]) => void, private readonly onNotice: (text: string, level?: 'info' | 'warn' | 'error') => void) {
    this.element.className = 'input-card glass-card';
    this.element.innerHTML = `
      <div class="section-title"><span>01</span><div><h2>选择输入</h2><p>拖拽本地文件，或粘贴允许 CORS 的网络 URL</p></div></div>
      <div class="drop-zone" tabindex="0">
        <input id="local-file-picker" name="localFiles" type="file" multiple hidden />
        <span class="drop-icon">⬡</span>
        <strong>拖拽文件到这里</strong>
        <em>支持 .ply / .spz / .splat / .sog / .ksplat / .lcc / meta.json</em>
      </div>
      <div class="url-row">
        <input id="remote-url-input" name="remoteUrl" class="url-input" type="url" placeholder="https://example.com/model.spz" />
        <button class="ghost-btn" data-action="add-url">添加 URL</button>
      </div>
      <p class="hint">URL 服务器必须返回 <code>Access-Control-Allow-Origin</code>，否则浏览器会拒绝下载。</p>
      <div class="file-list"></div>
    `;

    const input = this.element.querySelector<HTMLInputElement>('input[type="file"]')!;
    const zone = this.element.querySelector<HTMLElement>('.drop-zone')!;

    input.addEventListener('click', (event) => event.stopPropagation());
    zone.addEventListener('click', () => input.click());
    zone.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        input.click();
      }
    });
    input.addEventListener('change', async () => {
      if (input.files) await this.addFiles(await resolveLocalFiles(input.files));
      input.value = '';
    });

    zone.addEventListener('dragover', (event) => {
      event.preventDefault();
      zone.classList.add('dragging');
    });
    zone.addEventListener('dragleave', () => zone.classList.remove('dragging'));
    zone.addEventListener('drop', async (event) => {
      event.preventDefault();
      zone.classList.remove('dragging');
      if (event.dataTransfer?.files?.length) {
        await this.addFiles(await resolveLocalFiles(event.dataTransfer.files));
      }
    });

    this.element.querySelector('[data-action="add-url"]')?.addEventListener('click', async () => {
      const urlInput = this.element.querySelector<HTMLInputElement>('.url-input')!;
      const value = urlInput.value.trim();
      if (!value) return;
      try {
        this.onNotice('正在下载 URL 文件...', 'info');
        await this.addFiles([await resolveUrl(value)]);
        urlInput.value = '';
      } catch (error) {
        this.onNotice(error instanceof TypeError ? 'URL 下载失败：可能是 CORS 未允许跨域访问。' : String((error as Error).message || error), 'error');
      }
    });

    this.element.addEventListener('click', (event) => {
      const button = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-remove]');
      if (!button) return;
      this.files.splice(Number(button.dataset.remove), 1);
      this.renderList();
      this.onChange([...this.files]);
    });
  }

  get value(): InputFile[] {
    return [...this.files];
  }

  clear(): void {
    this.files = [];
    this.renderList();
    this.onChange([]);
  }

  private async addFiles(files: InputFile[]): Promise<void> {
    this.files.push(...files);
    for (const warning of getLargeFileWarnings(files)) this.onNotice(warning, 'warn');
    this.renderList();
    this.onChange([...this.files]);
  }

  private renderList(): void {
    const list = this.element.querySelector('.file-list') as HTMLElement;
    if (this.files.length === 0) {
      list.innerHTML = '<div class="empty-state">还没有选择文件</div>';
      return;
    }
    list.innerHTML = this.files.map((file, index) => `
      <div class="file-item">
        <div class="file-type">${extensionOf(file.name) || 'bin'}</div>
        <div class="file-info"><strong title="${file.name}">${file.name}</strong><span>${formatBytes(file.size)} · ${file.source}</span></div>
        <button class="icon-btn" data-remove="${index}" title="移除">×</button>
      </div>
    `).join('');
  }
}
